  ran = `${ran}${clause_P_LONG_KEY_512(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SECRET_512(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_TAG_LEN(t) ? "1" : "0"}`;
  const code: i32 = t.done();
  const nonce: string = toI32(process.argv.length) > 1 ? process.argv[1] : "-";
